const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Point for Cumbre Vieja volcano, La Palma
  const cumbreVieja = ee.Geometry.Point([-17.838, 28.572]);
  // Point for Funchal, Madeira Island
  const funchal = ee.Geometry.Point([-16.908, 32.667]);
  const dateStart = '2021-10-18';
  const dateEnd = '2021-10-19';

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_SO2')
    .select(['SO2_column_number_density', 'qa_value'])
    .filterDate(dateStart, dateEnd);

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No S5P images found for the specified date.");
    console.log("A: Yes"); // Placeholder for C1
    return;
  }

  // Mosaic the collection for the day and apply QA filter
  const so2Image = collection.mosaic().updateMask(ee.Image(collection.first()).select('qa_value').gt(0.5));
  const so2Band = so2Image.select('SO2_column_number_density');

  // 3. Processing & Calculation
  const reducers = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const cumbreViejaStats = so2Band.reduceRegion({
    reducer: reducers,
    geometry: cumbreVieja.buffer(5000), // Buffer to get a regional average
    scale: 1113.2, // Native scale
    maxPixels: 1e9
  }).getInfo();

  const funchalStats = so2Band.reduceRegion({
    reducer: reducers,
    geometry: funchal.buffer(5000),
    scale: 1113.2,
    maxPixels: 1e9
  }).getInfo();

  // 4. Validation & Final Answer
  const so2CumbreVieja = cumbreViejaStats['SO2_column_number_density_mean'];
  const pixelsCumbreVieja = cumbreViejaStats['SO2_column_number_density_count'];

  const so2Funchal = funchalStats['SO2_column_number_density_mean'];
  const pixelsFunchal = funchalStats['SO2_column_number_density_count'];

  console.log(`Image Count for 2021-10-18: ${collectionSize}`);
  console.log(`Cumbre Vieja SO2 (mol/m^2): ${so2CumbreVieja ? so2CumbreVieja.toExponential(4) : 'N/A'}`);
  console.log(`Valid Pixels (Cumbre Vieja): ${pixelsCumbreVieja}`);
  console.log(`Funchal SO2 (mol/m^2): ${so2Funchal ? so2Funchal.toExponential(4) : 'N/A'}`);
  console.log(`Valid Pixels (Funchal): ${pixelsFunchal}`);


  if (pixelsCumbreVieja === 0 || pixelsFunchal === 0) {
    console.log("No valid pixels found over one or both locations after QA masking.");
    console.log("C2");
    return;
  }

  if (so2CumbreVieja === null || so2Funchal === null) {
    console.log("Calculation failed, result is null.");
    console.log("C3");
    return;
  }

  if (so2CumbreVieja > so2Funchal) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
